/*
===== 기존 MediaSoup 코드 주석 처리 =====
모든 MediaSoup 관련 함수들은 향후 제거 예정

// mediasoup 방 참가
scwin.joinMediasoupRoom = async function() {
    return new Promise((resolve, reject) => {
        const timeout = setTimeout(() => {
            reject(new Error('방 참가 요청 시간 초과'));
        }, 10000);

        mediasoupSocket.emit('joinRoom', {
            roomId: currentUser.channelName,
            userData: {
                userId: currentUser.userId,
                name: currentUser.userName
            }
        }, (response) => {
            clearTimeout(timeout);

            if (response.success) {
                //console.log('✅ mediasoup 방 참가 성공');

                // Device 로드
                device.load({
                    routerRtpCapabilities: response.routerRtpCapabilities
                }).then(() => {
                    //console.log('✅ Device RTP Capabilities 로드 완료');
                    resolve();
                }).catch(error => {
                    //console.error('❌ Device 로드 실패:', error);
                    reject(error);
                });

            } else {
                //console.error('❌ 방 참가 실패:', response.error);
                reject(new Error(response.error));
            }
        });
    });
};

// Transport 생성
scwin.createTransports = async function() {
    // Send Transport 생성
    await scwin.createSendTransport();

    // Receive Transport 생성
    await scwin.createReceiveTransport();
};

// Send Transport 생성
scwin.createSendTransport = async function() {
    return new Promise((resolve, reject) => {
        const timeout = setTimeout(() => {
            reject(new Error('Send Transport 생성 시간 초과'));
        }, 15000); // 15초로 늘림

        //console.log('������ Send Transport 생성 요청 시작');

        mediasoupSocket.emit('createTransport', {
            type: 'send'
        }, (response) => {
            clearTimeout(timeout);

            try {
                if (!response.success) {
                    //console.error('❌ Send Transport 생성 실패:', response.error);
                    reject(new Error(response.error));
                    return;
                }

                //console.log('✅ Send Transport 서버 응답 수신:', {
                    transportId: response.transportId,
                    hasIceParameters: !!response.iceParameters,
                    hasIceCandidates: !!response.iceCandidates,
                    hasDtlsParameters: !!response.dtlsParameters
                });

                // 서버 응답 데이터 유효성 검사
                if (!response.transportId || !response.iceParameters || !response.iceCandidates || !response.dtlsParameters) {
                    //console.error('❌ Transport 생성 응답 데이터 불완전:', response);
                    reject(new Error('Transport 생성 응답 데이터가 불완전합니다'));
                    return;
                }

                // Device 상태 확인
                if (!device || !device.loaded) {
                    //console.error('❌ Device가 로드되지 않음:', {
                        deviceExists: !!device,
                        deviceLoaded: device?.loaded,
                        deviceHandlerName: device?.handlerName
                    });
                    reject(new Error('Device가 로드되지 않았습니다'));
                    return;
                }

                //console.log('������ Device 상태 확인:', {
                    loaded: device.loaded,
                    handlerName: device.handlerName,
                    rtpCapabilities: !!device.rtpCapabilities,
                    canProduce: device.canProduce('video')
                });

                // Send Transport 생성
                //console.log('������ Send Transport 생성 중...');
                sendTransport = device.createSendTransport({
                    id: response.transportId,
                    iceParameters: response.iceParameters,
                    iceCandidates: response.iceCandidates,
                    dtlsParameters: response.dtlsParameters
                });

                //console.log('✅ Send Transport 생성 완료:', {
                    id: sendTransport.id,
                    closed: sendTransport.closed,
                    connectionState: sendTransport.connectionState,
                    hasPeerConnection: !!sendTransport._pc,
                    transportType: typeof sendTransport,
                    transportKeys: Object.keys(sendTransport)
                });

                // PeerConnection 접근 방법 확인
                let peerConnection = null;

                // 방법 1: _pc 속성 직접 접근
                if (sendTransport._pc) {
                    peerConnection = sendTransport._pc;
                    //console.log('✅ PeerConnection 접근 방법 1 성공 (_pc)');
                } 
                // 방법 2: _handler.pc 접근
                else if (sendTransport._handler && sendTransport._handler.pc) {
                    peerConnection = sendTransport._handler.pc;
                    //console.log('✅ PeerConnection 접근 방법 2 성공 (_handler.pc)');
                } 
                // 방법 3: handler.pc 접근
                else if (sendTransport.handler && sendTransport.handler.pc) {
                    peerConnection = sendTransport.handler.pc;
                    //console.log('✅ PeerConnection 접근 방법 3 성공 (handler.pc)');
                }
                // 방법 4: 모든 속성 순회
                else {
                    //console.log('������ PeerConnection 찾기 위해 Transport 속성 순회');
                    for (const key in sendTransport) {
                        try {
                            const value = sendTransport[key];
                            if (value && typeof value === 'object' && value.constructor && value.constructor.name === 'RTCPeerConnection') {
                                peerConnection = value;
                                //console.log(`✅ PeerConnection 발견: ${key}`);
                                break;
                            }
                        } catch (e) {
                            // 접근 불가능한 속성은 무시
                        }
                    }
                }

                if (peerConnection) {
                    //console.log('������ PeerConnection 상태:', {
                        connectionState: peerConnection.connectionState,
                        iceConnectionState: peerConnection.iceConnectionState,
                        signalingState: peerConnection.signalingState,
                        iceGatheringState: peerConnection.iceGatheringState
                    });

                    // PeerConnection을 Transport에 저장 (나중에 접근하기 위해)
                    sendTransport._pc = peerConnection;
                } else {
                    //console.warn('⚠️ PeerConnection을 찾을 수 없음. Transport 내부 구조:', {
                        transportKeys: Object.keys(sendTransport),
                        handlerKeys: sendTransport._handler ? Object.keys(sendTransport._handler) : null
                    });
                }

                // Transport 이벤트 리스너 설정
                sendTransport.on('connect', async (params, callback, errback) => {
                    try {
                        //console.log('������ Send Transport connect 이벤트 발생');

                        const connectResponse = await new Promise((resolve, reject) => {
                            const connectTimeout = setTimeout(() => {
                                reject(new Error('Transport 연결 시간 초과'));
                            }, 10000);

                            mediasoupSocket.emit('connectTransport', {
                                transportId: sendTransport.id,
                                dtlsParameters: params.dtlsParameters
                            }, (response) => {
                                clearTimeout(connectTimeout);
                                if (response.success) {
                                    resolve(response);
                                } else {
                                    reject(new Error(response.error));
                                }
                            });
                        });

                        //console.log('✅ Send Transport 연결 성공');
                        callback();
                    } catch (error) {
                        //console.error('❌ Send Transport 연결 실패:', error);
                        errback(error);
                    }
                });

                sendTransport.on('produce', async (params, callback, errback) => {
                    try {
                        //console.log('������ Send Transport produce 이벤트 발생:', params.kind);

                        const produceResponse = await new Promise((resolve, reject) => {
                            const produceTimeout = setTimeout(() => {
                                reject(new Error('Producer 생성 시간 초과'));
                            }, 10000);

                            mediasoupSocket.emit('produce', {
                                transportId: sendTransport.id,
                                kind: params.kind,
                                rtpParameters: params.rtpParameters
                            }, (response) => {
                                clearTimeout(produceTimeout);
                                if (response.success) {
                                    resolve(response);
                                } else {
                                    reject(new Error(response.error));
                                }
                            });
                        });

                        //console.log('✅ Producer 생성 성공:', produceResponse.producerId);
                        callback({ id: produceResponse.producerId });
                    } catch (error) {
                        //console.error('❌ Producer 생성 실패:', error);
                        errback(error);
                    }
                });

                // Transport 상태 변경 이벤트 리스너
                sendTransport.on('connectionstatechange', (state) => {
                    //console.log('������ Send Transport 연결 상태 변경:', state);
                });

                sendTransport.on('icestatechange', (state) => {
                    //console.log('������ Send Transport ICE 상태 변경:', state);
                });

                //console.log('✅ Send Transport 이벤트 리스너 설정 완료');
                resolve();

            } catch (error) {
                //console.error('❌ Send Transport 생성 중 오류:', error);
                reject(error);
            }
        });
    });
};

// Receive Transport 생성
scwin.createReceiveTransport = async function() {
    return new Promise((resolve, reject) => {
        const timeout = setTimeout(() => {
            reject(new Error('Receive Transport 생성 시간 초과'));
        }, 15000); // 15초로 늘림

        //console.log('������ Receive Transport 생성 요청 시작');

        mediasoupSocket.emit('createTransport', {
            type: 'recv'
        }, (response) => {
            clearTimeout(timeout);

            try {
                if (!response.success) {
                    //console.error('❌ Receive Transport 생성 실패:', response.error);
                    reject(new Error(response.error));
                    return;
                }

                //console.log('✅ Receive Transport 서버 응답 수신:', {
                    transportId: response.transportId,
                    hasIceParameters: !!response.iceParameters,
                    hasIceCandidates: !!response.iceCandidates,
                    hasDtlsParameters: !!response.dtlsParameters
                });

                // 서버 응답 데이터 유효성 검사
                if (!response.transportId || !response.iceParameters || !response.iceCandidates || !response.dtlsParameters) {
                    //console.error('❌ Receive Transport 생성 응답 데이터 불완전:', response);
                    reject(new Error('Receive Transport 생성 응답 데이터가 불완전합니다'));
                    return;
                }

                // Device 상태 확인
                if (!device || !device.loaded) {
                    console.error('❌ Device가 로드되지 않음');
                    reject(new Error('Device가 로드되지 않았습니다'));
                    return;
                }

                // Receive Transport 생성
                //console.log('������ Receive Transport 생성 중...');
                recvTransport = device.createRecvTransport({
                    id: response.transportId,
                    iceParameters: response.iceParameters,
                    iceCandidates: response.iceCandidates,
                    dtlsParameters: response.dtlsParameters
                });

                //console.log('✅ Receive Transport 생성 완료:', {
                    id: recvTransport.id,
                    closed: recvTransport.closed,
                    connectionState: recvTransport.connectionState,
                    hasPeerConnection: !!recvTransport._pc,
                    transportType: typeof recvTransport
                });

                // PeerConnection 접근 방법 확인
                let peerConnection = null;

                if (recvTransport._pc) {
                    peerConnection = recvTransport._pc;
                    //console.log('✅ Receive PeerConnection 접근 방법 1 성공 (_pc)');
                } else if (recvTransport._handler && recvTransport._handler.pc) {
                    peerConnection = recvTransport._handler.pc;
                    //console.log('✅ Receive PeerConnection 접근 방법 2 성공 (_handler.pc)');
                } else if (recvTransport.handler && recvTransport.handler.pc) {
                    peerConnection = recvTransport.handler.pc;
                    //console.log('✅ Receive PeerConnection 접근 방법 3 성공 (handler.pc)');
                }

                if (peerConnection) {
                    //console.log('������ Receive PeerConnection 상태:', {
                        connectionState: peerConnection.connectionState,
                        iceConnectionState: peerConnection.iceConnectionState,
                        signalingState: peerConnection.signalingState
                    });

                    // PeerConnection을 Transport에 저장
                    recvTransport._pc = peerConnection;

                    // ontrack 이벤트 리스너 설정
                    peerConnection.ontrack = (event) => {
                        //console.log('������ Receive Transport ontrack 이벤트 발생!', {
                            streams: event.streams.length,
                            track: event.track.kind,
                            trackId: event.track.id,
                            trackReadyState: event.track.readyState
                        });

                        if (event.streams.length > 0) {
                            const stream = event.streams[0];
                            //console.log('✅ Transport에서 MediaStream 수신:', {
                                streamId: stream.id,
                                trackCount: stream.getTracks().length
                            });

                            // 임시 사용자 이름으로 표시
                            const tempUserName = `사용자_${Date.now()}`;
                            displayRemoteVideo(stream, tempUserName);
                        }
                    };
                } else {
                    //console.warn('⚠️ Receive PeerConnection을 찾을 수 없음');
                }

                // Transport 이벤트 리스너 설정
                recvTransport.on('connect', async (params, callback, errback) => {
                    try {
                        //console.log('������ Receive Transport connect 이벤트 발생');

                        const connectResponse = await new Promise((resolve, reject) => {
                            const connectTimeout = setTimeout(() => {
                                reject(new Error('Receive Transport 연결 시간 초과'));
                            }, 10000);

                            mediasoupSocket.emit('connectTransport', {
                                transportId: recvTransport.id,
                                dtlsParameters: params.dtlsParameters
                            }, (response) => {
                                clearTimeout(connectTimeout);
                                if (response.success) {
                                    resolve(response);
                                } else {
                                    reject(new Error(response.error));
                                }
                            });
                        });

                        //console.log('✅ Receive Transport 연결 성공');
                        callback();
                    } catch (error) {
                        //console.error('❌ Receive Transport 연결 실패:', error);
                        errback(error);
                    }
                });

                // Transport 상태 변경 이벤트 리스너
                recvTransport.on('connectionstatechange', (state) => {
                    //console.log('������ Receive Transport 연결 상태 변경:', state);
                });

                recvTransport.on('icestatechange', (state) => {
                    //console.log('������ Receive Transport ICE 상태 변경:', state);
                });

                //console.log('✅ Receive Transport 이벤트 리스너 설정 완료');
                resolve();

            } catch (error) {
                //console.error('❌ Receive Transport 생성 중 오류:', error);
                reject(error);
            }
        });
    });
};

// Producer 생성 (로컬 스트림 전송)
scwin.startProducing = async function() {
    if (!localStream) {
        throw new Error('로컬 스트림이 없습니다');
    }

    // 비디오 Producer 생성
    const videoTrack = localStream.getVideoTracks()[0];
    if (videoTrack) {
        videoProducer = await sendTransport.produce({
            track: videoTrack
        });
        //console.log('✅ Video Producer 생성:', videoProducer.id);
    }

    // 오디오 Producer 생성
    const audioTrack = localStream.getAudioTracks()[0];
    if (audioTrack) {
        audioProducer = await sendTransport.produce({
            track: audioTrack
        });
        //console.log('✅ Audio Producer 생성:', audioProducer.id);
    }
};

// 기존 Producer들 소비
scwin.consumeExistingProducers = async function() {
    return new Promise((resolve, reject) => {
        mediasoupSocket.emit('getExistingProducers', (response) => {
            if (response.success) {
                //console.log('������ 기존 Producer들:', response.producers.length, '개');
                //console.log('기존 Producer 목록:', response.producers);

                // 기존 Producer의 사용자 정보도 저장
                response.producers.forEach(producer => {
                    if (producer.userData && !remoteUserInfo.has(producer.peerId)) {
                        const userInfo = {
                            userId: producer.userData.userId || producer.peerId,
                            name: producer.userData.name || producer.userData.userName || `사용자_${producer.peerId.slice(-4)}`,
                            userName: producer.userData.userName || producer.userData.name || `사용자_${producer.peerId.slice(-4)}`
                        };
                        remoteUserInfo.set(producer.peerId, userInfo);
                        //console.log('✅ 기존 Producer 사용자 정보 저장:', producer.peerId, '→', userInfo);
                    }
                });

                // 각 Producer에 대해 Consumer 생성
                const consumePromises = response.producers.map(producer => 
                    scwin.consumeStream(producer.peerId, producer.producerId)
                );

                Promise.all(consumePromises).then(() => {
                    //console.log('✅ 모든 기존 Producer 소비 완료');
                    resolve();
                }).catch(error => {
                    //console.error('❌ 기존 Producer 소비 실패:', error);
                    reject(error);
                });
            } else {
                //console.error('❌ 기존 Producer 조회 실패:', response.error);
                reject(new Error(response.error));
            }
        });
    });
};

// 스트림 소비 (Consumer 생성)
scwin.consumeStream = async function(peerId, producerId) {
    try {
        //console.log('������ 스트림 소비 시작:', peerId, producerId);

        // Transport 상태 확인
        if (!recvTransport) {
            throw new Error('Receive Transport가 없습니다');
        }

        //console.log('������ Receive Transport 상태:', {
            id: recvTransport.id,
            closed: recvTransport.closed,
            connectionState: recvTransport.connectionState
        });

        const response = await new Promise((resolve, reject) => {
            mediasoupSocket.emit('consume', {
                peerId: peerId,
                producerId: producerId,
                rtpCapabilities: device.rtpCapabilities
            }, (response) => {
                if (response.success) {
                    resolve(response);
                } else {
                    reject(new Error(response.error));
                }
            });
        });

        //console.log('������ Consumer 생성 요청:', {
            id: response.consumerId,
            producerId: producerId,
            kind: response.kind,
            rtpParameters: !!response.rtpParameters
        });

        // Consumer 생성 전에 ontrack 이벤트 리스너 설정
        if (recvTransport && recvTransport._pc) {
            const pc = recvTransport._pc;

            // 기존 ontrack 이벤트 제거 (중복 방지)
            pc.ontrack = null;

            // 새로운 ontrack 이벤트 리스너 설정
            pc.ontrack = (event) => {
                //console.log('������ ontrack 이벤트 발생!', {
                    streams: event.streams.length,
                    track: event.track.kind,
                    trackId: event.track.id,
                    trackReadyState: event.track.readyState
                });

                if (event.streams.length > 0) {
                    const stream = event.streams[0];
                    //console.log('✅ ontrack에서 MediaStream 수신:', {
                        streamId: stream.id,
                        trackCount: stream.getTracks().length
                    });

                    // 즉시 표시
                    scwin.displayRemoteVideoDirectly(peerId, stream, response.kind);
                } else if (event.track) {
                    // 스트림이 없으면 track으로 직접 MediaStream 생성
                    const stream = new MediaStream([event.track]);
                    //console.log('✅ ontrack에서 track으로 MediaStream 생성');
                    scwin.displayRemoteVideoDirectly(peerId, stream, response.kind);
                }
            };

            //console.log('✅ ontrack 이벤트 리스너 설정 완료');
        }

        const consumer = await recvTransport.consume({
            id: response.consumerId,
            producerId: producerId,
            kind: response.kind,
            rtpParameters: response.rtpParameters
        });

        //console.log('������ Consumer 생성 직후 상태:', {
            consumer: !!consumer,
            consumerType: typeof consumer,
            consumerKeys: Object.keys(consumer || {}),
            consumerProto: Object.getPrototypeOf(consumer || {}).constructor.name
        });

        //console.log('✅ Consumer 생성 성공:', {
            id: consumer.id,
            kind: consumer.kind,
            track: consumer.track,
            trackType: typeof consumer.track,
            trackId: consumer.track?.id,
            trackKind: consumer.track?.kind,
            trackReadyState: consumer.track?.readyState
        });

        // Consumer 이벤트 리스닝
        consumer.on('trackended', () => {
            //console.log('������ Consumer track ended:', consumer.id);
        });

        consumer.on('transportclose', () => {
            console.log('������ Consumer transport closed:', consumer.id);
        });

        // track이 준비되었는지 확인하는 여러 방법
        //console.log('������ Track 준비 상태 확인:', {
            hasTrack: !!consumer.track,
            trackReady: consumer.track?.readyState === 'live'
        });

        // Consumer 저장
        consumers.set(consumer.id, { consumer, peerId });

        // Consumer 재생 시작
        await new Promise((resolve, reject) => {
            mediasoupSocket.emit('resumeConsumer', {
                consumerId: consumer.id
            }, (response) => {
                if (response.success) {
                    //console.log('✅ Consumer 재생 시작 성공:', consumer.id);
                    resolve();
                } else {
                    reject(new Error(response.error));
                }
            });
        });

        // Consumer resume 후 즉시 track 강제 생성 시도
        //console.log('������ Consumer resume 후 track 강제 생성 시도');
        try {
            // 방법 1: Consumer의 내부 메서드 호출 시도
            if (typeof consumer._getTrack === 'function') {
                consumer.track = consumer._getTrack();
                //console.log('✅ _getTrack으로 track 생성 성공');
            }
            // 방법 2: Consumer의 rtpReceiver에서 track 추출
            else if (consumer.rtpReceiver && consumer.rtpReceiver.track) {
                consumer.track = consumer.rtpReceiver.track;
                //console.log('✅ rtpReceiver에서 track 추출 성공');
            }
            // 방법 3: Consumer 재초기화 시도
            else if (typeof consumer._createTrack === 'function') {
                consumer._createTrack();
                //console.log('✅ _createTrack 호출 성공');
            }
        } catch (e) {
            //console.log('⚠️ track 강제 생성 실패:', e.message);
        }

        // Consumer 생성 후 즉시 PeerConnection에서 MediaStream 추출 시도
        //console.log('������ Consumer 생성 완료, 즉시 PeerConnection에서 MediaStream 추출 시도');

        // 즉시 PeerConnection에서 MediaStream 추출 (track null이어도)
        try {
            if (recvTransport && recvTransport._pc) {
                const pc = recvTransport._pc;
                //console.log('������ PeerConnection 상태 확인:', {
                    connectionState: pc.connectionState,
                    iceConnectionState: pc.iceConnectionState,
                    signalingState: pc.signalingState
                });

                // 방법 1: 모든 Receiver에서 live track 수집
                const receivers = pc.getReceivers();
                //console.log('������ 총 RTP Receivers:', receivers.length);

                const liveTracks = [];
                receivers.forEach((receiver, index) => {
                    //console.log(`������ Receiver ${index}:`, {
                        track: !!receiver.track,
                        trackKind: receiver.track?.kind,
                        trackId: receiver.track?.id,
                        trackReadyState: receiver.track?.readyState,
                        trackEnabled: receiver.track?.enabled
                    });

                    if (receiver.track && receiver.track.readyState === 'live') {
                        liveTracks.push(receiver.track);
                        //console.log(`✅ Live track 발견: ${receiver.track.kind} (${receiver.track.id})`);
                    }
                });

                if (liveTracks.length > 0) {
                    console.log(`������ 총 ${liveTracks.length}개의 live track 발견! MediaStream 생성`);
                    const stream = new MediaStream(liveTracks);

                    //console.log('✅ PeerConnection에서 MediaStream 생성 성공:', {
                        streamId: stream.id,
                        trackCount: stream.getTracks().length,
                        videoTracks: stream.getVideoTracks().length,
                        audioTracks: stream.getAudioTracks().length
                    });

                    // 즉시 표시
                    scwin.displayRemoteVideoDirectly(peerId, stream, consumer.kind);
                    //console.log('✅ 스트림 소비 완료 (PeerConnection 방식):', consumer.id);
                    return; // 성공 시 더 이상 진행하지 않음
                }
            }
        } catch (e) {
            //console.error('❌ 즉시 PeerConnection 추출 실패:', e);
        }

        // Consumer 생성 후 초기 대기 시간 (500ms)
        //console.log('⏳ Consumer 생성 후 초기 대기 중...');
        setTimeout(() => {
            //console.log('������ Consumer 초기 대기 완료, track 상태 확인 시작');

            // track이 준비될 때까지 여러 번 시도 (최대 30초)
            let attemptCount = 0;
            const maxAttempts = 150; // 30초 (200ms * 150)

            const checkTrackReady = () => {
                attemptCount++;

                // Consumer 상세 상태 확인
                //console.log(`������ Consumer track 상태 확인 (시도 ${attemptCount}/${maxAttempts}):`, {
                    // 기본 track 접근
                    trackExists: !!consumer.track,
                    trackType: typeof consumer.track,
                    trackId: consumer.track?.id,
                    trackKind: consumer.track?.kind,
                    trackReadyState: consumer.track?.readyState,
                    trackEnabled: consumer.track?.enabled,
                    trackMuted: consumer.track?.muted,
                    // rtpReceiver 통한 접근
                    hasRtpReceiver: !!consumer.rtpReceiver,
                    rtpReceiverTrack: consumer.rtpReceiver?.track,
                    rtpReceiverTrackType: typeof consumer.rtpReceiver?.track,
                    rtpReceiverTrackId: consumer.rtpReceiver?.track?.id,
                    rtpReceiverTrackKind: consumer.rtpReceiver?.track?.kind,
                    rtpReceiverTrackReadyState: consumer.rtpReceiver?.track?.readyState,
                    // Consumer 전체 상태
                    consumerClosed: consumer.closed,
                    consumerPaused: consumer.paused,
                    consumerProducerPaused: consumer.producerPaused
                });

                // 1순위: consumer.track 직접 접근
                if (consumer.track && consumer.track instanceof MediaStreamTrack) {
                    //console.log('✅ Track 준비됨! (직접 접근) 원격 비디오 표시 시작');
                    scwin.displayRemoteVideo(peerId, consumer);
                    return;
                }

                // 2순위: rtpReceiver.track 접근
                if (consumer.rtpReceiver && consumer.rtpReceiver.track && consumer.rtpReceiver.track instanceof MediaStreamTrack) {
                    //console.log('✅ Track 준비됨! (rtpReceiver 접근) 원격 비디오 표시 시작');
                    // consumer.track에 rtpReceiver.track 할당
                    consumer.track = consumer.rtpReceiver.track;
                    scwin.displayRemoteVideo(peerId, consumer);
                    return;
                }

                // 3순위: rtpReceiver가 있으면 MediaStream 직접 생성 (track null이어도)
                if (consumer.rtpReceiver && attemptCount >= 5) {
                    //console.log('������ rtpReceiver 발견! MediaStream 직접 생성 시도');
                    try {
                        const stream = new MediaStream();

                        // rtpReceiver를 MediaStream에 연결하는 다양한 방법 시도
                        if (consumer.rtpReceiver.track) {
                            stream.addTrack(consumer.rtpReceiver.track);
                            //console.log('✅ rtpReceiver.track을 MediaStream에 추가 성공');
                        } else {
                            // track이 없어도 rtpReceiver 자체를 활용
                            //console.log('������ rtpReceiver에서 track 강제 생성 시도');

                            // 브라우저 내부 API 사용 시도
                            if (consumer.rtpReceiver.getContributingSources) {
                                const sources = consumer.rtpReceiver.getContributingSources();
                                //console.log('������ RTP 소스 정보:', sources);
                            }

                            // PC의 트랜시버를 통한 접근 시도
                            if (recvTransport && recvTransport._pc) {
                                const transceivers = recvTransport._pc.getTransceivers();
                                //console.log('������ Transceivers:', transceivers.length);

                                for (const transceiver of transceivers) {
                                    if (transceiver.receiver === consumer.rtpReceiver && transceiver.receiver.track) {
                                        stream.addTrack(transceiver.receiver.track);
                                        //console.log('✅ Transceiver에서 track 추출 성공!');
                                        break;
                                    }
                                }
                            }
                        }

                        if (stream.getTracks().length > 0) {
                            //console.log('✅ MediaStream 생성 성공, 직접 표시');
                            scwin.displayRemoteVideoDirectly(peerId, stream, consumer.kind);
                            return;
                        }
                    } catch (e) {
                        //console.error('❌ MediaStream 직접 생성 실패:', e);
                    }
                }

                if (attemptCount < maxAttempts) {
                    //console.log('⏳ Track 아직 준비 안됨, 재시도...');
                    setTimeout(checkTrackReady, 200);
                } else {
                    //console.error('❌ Track 준비 시간 초과 (30초). WebRTC PeerConnection에서 직접 추출 시도');

                    // 최후 수단: WebRTC PeerConnection에서 직접 MediaStream 추출
                    try {
                        if (recvTransport && recvTransport._pc) {
                            const pc = recvTransport._pc;
                            //console.log('������ PeerConnection에서 직접 MediaStream 추출 시도');

                            // 방법 1: getRemoteStreams() 사용 (구버전 API)
                            if (typeof pc.getRemoteStreams === 'function') {
                                const remoteStreams = pc.getRemoteStreams();
                                //console.log('������ Remote Streams:', remoteStreams.length);

                                if (remoteStreams.length > 0) {
                                    const stream = remoteStreams[remoteStreams.length - 1]; // 최신 스트림
                                    //console.log('✅ getRemoteStreams()에서 MediaStream 추출 성공');
                                    scwin.displayRemoteVideoDirectly(peerId, stream, consumer.kind);
                                    return;
                                }
                            }

                            // 방법 2: getReceivers()를 통한 track 수집
                            const receivers = pc.getReceivers();
                            //console.log('������ RTP Receivers:', receivers.length);

                            const tracks = [];
                            receivers.forEach(receiver => {
                                if (receiver.track && receiver.track.readyState === 'live') {
                                    tracks.push(receiver.track);
                                    //console.log('✅ Receiver에서 live track 발견:', receiver.track.kind);
                                }
                            });

                            if (tracks.length > 0) {
                                const stream = new MediaStream(tracks);
                                //console.log('✅ Receivers에서 MediaStream 생성 성공');
                                scwin.displayRemoteVideoDirectly(peerId, stream, consumer.kind);
                                return;
                            }

                            // 방법 3: ontrack 이벤트 강제 발생 시도
                            //console.log('������ ontrack 이벤트 리스너 설정');
                            pc.ontrack = (event) => {
                                //console.log('✅ ontrack 이벤트 발생!', event.streams.length);
                                if (event.streams.length > 0) {
                                    scwin.displayRemoteVideoDirectly(peerId, event.streams[0], consumer.kind);
                                }
                            };
                        }
                    } catch (e) {
                        //console.error('❌ PeerConnection에서 MediaStream 추출 실패:', e);
                    }

                    // 최종 실패 시 기본 방법 시도
                    scwin.displayRemoteVideo(peerId, consumer);
                }
            };

            // track 상태 확인 시작
            checkTrackReady();
        }, 500);

        //console.log('✅ 스트림 소비 완료:', consumer.id);

    } catch (error) {
        //console.error('❌ 스트림 소비 실패:', error);
    }
};

// 원격 비디오 표시 (mediasoup Consumer 방식) - 완전 개선된 버전
scwin.displayRemoteVideo = function(peerId, consumer) {
    //console.log('������ 원격 비디오 표시 시작:', peerId, consumer?.kind);

    // Consumer 유효성 검사
    if (!consumer) {
        //console.error('❌ Consumer가 null/undefined:', consumer);
        return;
    }

    //console.log('������ Consumer 상세 정보:', {
        id: consumer.id,
        kind: consumer.kind,
        track: consumer.track,
        trackType: typeof consumer.track,
        consumerType: typeof consumer,
        hasTrack: 'track' in consumer,
        trackConstructor: consumer.track?.constructor?.name
    });

    // track 접근 여러 방법 시도 (우선순위별로)
    let track = null;

    // 방법 1: 직접 접근
    if (consumer.track && consumer.track instanceof MediaStreamTrack) {
        track = consumer.track;
        //console.log('✅ 방법 1 성공: 직접 track 접근');
    }
    // 방법 2: rtpReceiver를 통한 접근
    else if (consumer.rtpReceiver && consumer.rtpReceiver.track && consumer.rtpReceiver.track instanceof MediaStreamTrack) {
        track = consumer.rtpReceiver.track;
        //console.log('✅ 방법 2 성공: rtpReceiver track 접근');
    }
    // 방법 3: getter를 통한 접근 (mediasoup에서 track이 getter일 수 있음)
    else if (typeof consumer.track === 'function') {
        try {
            track = consumer.track();
            //console.log('✅ 방법 3 성공: track() 함수 호출');
        } catch (e) {
            //console.log('⚠️ 방법 3 실패:', e.message);
        }
    }
    // 방법 4: 다른 속성명 시도
    else if (consumer.mediaStreamTrack) {
        track = consumer.mediaStreamTrack;
        //console.log('✅ 방법 4 성공: mediaStreamTrack 속성');
    }
    // 방법 5: _track 내부 속성 (최후 수단)
    else if (consumer._track) {
        track = consumer._track;
        //console.log('✅ 방법 5 성공: _track 내부 속성');
    }

    if (!track) {
        //console.error('❌ 모든 방법으로 track 접근 실패');
        //console.error('Consumer 전체 객체:', consumer);
        //console.error('Consumer keys:', Object.keys(consumer));

        // Consumer 객체 구조 완전 분석
        //console.error('������ Consumer 객체 상세 분석:', {
            // 기본 속성
            id: consumer.id,
            kind: consumer.kind,
            closed: consumer.closed,
            paused: consumer.paused,
            producerPaused: consumer.producerPaused,
            // track 관련
            track: consumer.track,
            trackType: typeof consumer.track,
            trackConstructor: consumer.track?.constructor?.name,
            // rtpReceiver 관련
            rtpReceiver: consumer.rtpReceiver,
            rtpReceiverType: typeof consumer.rtpReceiver,
            rtpReceiverTrack: consumer.rtpReceiver?.track,
            rtpReceiverTrackType: typeof consumer.rtpReceiver?.track,
            // rtpParameters
            rtpParameters: consumer.rtpParameters,
            // 프로토타입 체인
            protoKeys: Object.keys(Object.getPrototypeOf(consumer)),
            protoProtoKeys: Object.keys(Object.getPrototypeOf(Object.getPrototypeOf(consumer))),
            // 모든 속성 확인
            allOwnProperties: Object.getOwnPropertyNames(consumer),
            // 내부 속성 확인
            hasInternalTrack: '_track' in consumer,
            hasMediaStreamTrack: 'mediaStreamTrack' in consumer,
            hasGetTrack: 'getTrack' in consumer,
            // 기타 가능한 속성들
            stream: consumer.stream,
            streams: consumer.streams,
            receiver: consumer.receiver,
            transceiver: consumer.transceiver
        });

        // 최후 수단: Consumer 객체의 모든 속성 순회
        //console.error('������ Consumer 모든 속성 순회:');
        for (const key in consumer) {
            try {
                const value = consumer[key];
                //console.error(`  ${key}:`, value, typeof value);
                if (value && typeof value === 'object' && value.constructor && value.constructor.name === 'MediaStreamTrack') {
                    //console.error(`  ������ MediaStreamTrack 발견: ${key}`);
                    track = value;
                    break;
                }
            } catch (e) {
               //console.error(`  ${key}: (접근 불가) ${e.message}`);
            }
        }

        if (!track) {
           //console.error('❌ 완전한 분석 후에도 track 발견 불가');
            //console.error('������ 대안 방법 시도: Consumer 없이 MediaStream 생성');

            // 대안 방법 1: Consumer의 rtpReceiver를 통한 MediaStream 생성
            if (consumer.rtpReceiver) {
                try {
                    const stream = new MediaStream();
                    // rtpReceiver가 있으면 이를 통해 track 생성 시도
                    //console.log('������ rtpReceiver를 통한 MediaStream 생성 시도');

                    // rtpReceiver에서 track 추출 시도
                    const rtpTrack = consumer.rtpReceiver.track;
                    if (rtpTrack) {
                        stream.addTrack(rtpTrack);
                        //console.log('✅ rtpReceiver에서 track 추출 성공');

                        // 원격 비디오 표시 (stream 직접 사용)
                        scwin.displayRemoteVideoDirectly(peerId, stream, consumer.kind);
                        return;
                    }
                } catch (e) {
                    //console.error('❌ rtpReceiver를 통한 MediaStream 생성 실패:', e);
                }
            }

            // 대안 방법 2: Consumer를 MediaStream으로 직접 변환 시도
            if (consumer.stream) {
                //console.log('������ Consumer.stream 직접 사용');
                scwin.displayRemoteVideoDirectly(peerId, consumer.stream, consumer.kind);
                return;
            }

            //console.error('❌ 모든 대안 방법도 실패');
            return;
        } else {
            //console.log('✅ 속성 순회로 track 발견!');
        }
    }

    // track이 MediaStreamTrack인지 확인
    if (!(track instanceof MediaStreamTrack)) {
        //console.error('❌ 추출된 track이 MediaStreamTrack이 아님:', typeof track, track);
        return;
    }

    //console.log('✅ Track 유효성 확인 완료:', {
        kind: track.kind,
        id: track.id,
        readyState: track.readyState,
        enabled: track.enabled,
        muted: track.muted
    });

    // 기존 정보 확인
    let remoteVideoInfo = remoteVideos.get(peerId);

    if (!remoteVideoInfo) {
        // 새로운 원격 비디오 컨테이너 생성
        const container = document.createElement("div");
        container.className = "remote-user-video";
        container.id = `remote-${peerId}`;

        const videoWrapper = document.createElement("div");
        videoWrapper.className = "remote-video-wrapper";

        const videoPlayer = document.createElement("div");
        videoPlayer.className = "remote-video-player";

        const video = document.createElement("video");
        video.autoplay = true;
        video.playsInline = true;
        video.muted = false;
        video.controls = false;

        // 사용자 이름 표시 (개선된 버전)
        const userName = document.createElement("div");
        userName.className = "remote-user-name";

        // 사용자 정보 가져오기 (여러 방법 시도)
        const userInfo = remoteUserInfo.get(peerId);
        let displayName = `사용자_${peerId.slice(-4)}`;

        if (userInfo) {
            if (userInfo.name) {
                displayName = userInfo.name;
            } else if (userInfo.userName) {
                displayName = userInfo.userName;
            }
        }

        userName.textContent = displayName;
        //console.log('������ 사용자 이름 설정:', peerId, '→', displayName);

        // DOM 구성
        videoPlayer.appendChild(video);
        videoWrapper.appendChild(videoPlayer);
        container.appendChild(videoWrapper);
        container.appendChild(userName);

        // 그리드에 추가
        const remoteGrid = document.getElementById("remoteVideosGrid");
        if (remoteGrid) {
            remoteGrid.appendChild(container);
        }

        // MediaStream 생성
        const mediaStream = new MediaStream();

        // 정보 저장
        remoteVideoInfo = {
            container,
            video,
            stream: mediaStream,
            tracks: new Map(),
            userName: displayName
        };
        remoteVideos.set(peerId, remoteVideoInfo);

        // 비디오에 stream 연결
        video.srcObject = mediaStream;

        //console.log('✅ 원격 비디오 컨테이너 생성 완료:', peerId);
    }

    try {
        // 트랙이 이미 추가되었는지 확인
        const existingTrack = remoteVideoInfo.tracks.get(consumer.id);
        if (existingTrack) {
            //console.log('⚠️ 트랙이 이미 존재함:', consumer.id);
            return;
        }

        // MediaStream에 트랙 추가
        remoteVideoInfo.stream.addTrack(track);
        remoteVideoInfo.tracks.set(consumer.id, track);

        //console.log(`✅ ${consumer.kind} 트랙 추가 성공:`, peerId, track.id);

        // 비디오 재생 시도
        const playPromise = remoteVideoInfo.video.play();

        if (playPromise !== undefined) {
            playPromise.then(() => {
                //console.log('✅ 원격 비디오 재생 성공:', peerId);
                //scwin.addChatMessage("시스템", `✅ ${remoteVideoInfo.userName}님과 영상통화가 연결되었습니다!`, false);
            }).catch(error => {
                //console.error('❌ 비디오 자동재생 실패 (사용자 상호작용 필요):', error);
                // 자동재생 실패 시 사용자에게 알림
                setTimeout(() => {
                    remoteVideoInfo.video.play().catch(err => {
                        //console.log('비디오 재생을 위해 사용자 클릭이 필요할 수 있습니다.');
                    });
                }, 1000);
            });
        }

    } catch (error) {
        //console.error('❌ MediaStream addTrack 실패:', error);
        //console.error('Consumer 정보:', consumer);
        //console.error('Track 정보:', track);
        //console.error('Track type:', typeof track);
        //console.error('Track constructor:', track?.constructor?.name);
    }
};

// 원격 비디오 표시 (MediaStream 직접 사용)
scwin.displayRemoteVideoDirectly = function(peerId, stream, kind) {
    try {
        //console.log('������ 원격 비디오 직접 표시 시작:', peerId, kind);

        if (!stream || !(stream instanceof MediaStream)) {
            //console.error('❌ 유효하지 않은 MediaStream:', stream);
            return;
        }

        //console.log('✅ MediaStream 유효성 확인:', {
            streamId: stream.id,
            trackCount: stream.getTracks().length,
            videoTracks: stream.getVideoTracks().length,
            audioTracks: stream.getAudioTracks().length
        });

        // 기존 정보 확인
        let remoteVideoInfo = remoteVideos.get(peerId);
        if (!remoteVideoInfo) {
            // 새로운 사용자 정보 생성
            //console.log('������️ 새로운 원격 비디오 컨테이너 생성:', peerId);

            // 컨테이너 생성
            const container = document.createElement("div");
            container.className = "remote-video-container";
            container.id = `remote-${peerId}`;

            const videoWrapper = document.createElement("div");
            videoWrapper.className = "video-wrapper";

            const videoPlayer = document.createElement("div");
            videoPlayer.className = "video-player";

            const video = document.createElement("video");
            video.className = "remote-video";
            video.autoplay = true;
            video.playsInline = true;
            video.muted = false;
            video.controls = false;

            // 사용자 이름 표시
            const userName = document.createElement("div");
            userName.className = "remote-user-name";

            // 사용자 정보 가져오기
            const userInfo = remoteUserInfo.get(peerId);
            let displayName = `사용자_${peerId.slice(-4)}`;

            if (userInfo) {
                if (userInfo.name) {
                    displayName = userInfo.name;
                } else if (userInfo.userName) {
                    displayName = userInfo.userName;
                }
            }

            userName.textContent = displayName;
           //console.log('������ 사용자 이름 설정:', peerId, '→', displayName);

            // DOM 구성
            videoPlayer.appendChild(video);
            videoWrapper.appendChild(videoPlayer);
            container.appendChild(videoWrapper);
            container.appendChild(userName);

            // 그리드에 추가
            const remoteGrid = document.getElementById("remoteVideosGrid");
            if (remoteGrid) {
                remoteGrid.appendChild(container);
            }

            // 정보 저장
            remoteVideoInfo = {
                container,
                video,
                stream: stream,
                tracks: new Map(),
                userName: displayName
            };
            remoteVideos.set(peerId, remoteVideoInfo);

            // 비디오에 stream 연결
            video.srcObject = stream;

        } else {
            // 기존 MediaStream에 새 트랙 추가
            //console.log('������ 기존 컨테이너에 트랙 추가:', peerId);
            stream.getTracks().forEach(track => {
                if (!remoteVideoInfo.tracks.has(track.id)) {
                    remoteVideoInfo.stream.addTrack(track);
                    remoteVideoInfo.tracks.set(track.id, track);
                }
            });
        }

        // 비디오 재생 시도
        const playPromise = remoteVideoInfo.video.play();

        if (playPromise !== undefined) {
            playPromise.then(() => {
                //console.log('✅ 원격 비디오 재생 성공:', peerId);
                //scwin.addChatMessage("시스템", `✅ ${remoteVideoInfo.userName}님과 영상통화가 연결되었습니다!`, false);
            }).catch(error => {
                //console.error('❌ 비디오 자동재생 실패 (사용자 상호작용 필요):', error);
                // 자동재생 실패 시 사용자에게 알림
                setTimeout(() => {
                    remoteVideoInfo.video.play().catch(err => {
                        //console.log('비디오 재생을 위해 사용자 클릭이 필요할 수 있습니다.');
                    });
                }, 1000);
            });
        }

        //console.log(`✅ ${kind} 직접 표시 완료:`, peerId, stream.id);

    } catch (error) {
        //console.error('❌ 원격 비디오 직접 표시 실패:', error);
        //console.error('Stream 정보:', stream);
    }
};

// 원격 사용자 제거
scwin.removeRemoteUser = function(peerId) {
    //console.log('������️ 원격 사용자 제거:', peerId);

    // Consumer 정리
    consumers.forEach((consumerInfo, consumerId) => {
        if (consumerInfo.peerId === peerId) {
            consumerInfo.consumer.close();
            consumers.delete(consumerId);
        }
    });

    // 비디오 정리
    const remoteVideoInfo = remoteVideos.get(peerId);
    if (remoteVideoInfo) {
        if (remoteVideoInfo.container && remoteVideoInfo.container.parentNode) {
            remoteVideoInfo.container.parentNode.removeChild(remoteVideoInfo.container);
        }
        remoteVideos.delete(peerId);
    }

    //console.log('✅ 원격 사용자 정리 완료:', peerId);
};

// 화상통화 나가기
scwin.leaveCall = function() {
    console.log("=== leaveCall 함수 시작 ===");
    try {
        console.log("화상통화 나가기 시작");

        // Producer 정리
        if (videoProducer) {
            videoProducer.close();
            videoProducer = null;
        }
        if (audioProducer) {
            audioProducer.close();
            audioProducer = null;
        }

        // Consumer 정리
        consumers.forEach(consumerInfo => {
            consumerInfo.consumer.close();
        });
        consumers.clear();

        // Transport 정리
        if (sendTransport) {
            sendTransport.close();
            sendTransport = null;
        }
        if (recvTransport) {
            recvTransport.close();
            recvTransport = null;
        }

        // Device 정리
        if (device) {
            device = null;
        }

        // 로컬 스트림 정리
        if (localStream) {
            localStream.getTracks().forEach(track => track.stop());
            localStream = null;
        }

        const localVideo = document.getElementById("localVideo");
        if (localVideo) {
            localVideo.srcObject = null;
        }

        // 원격 비디오 정리
        remoteVideos.forEach((videoInfo, peerId) => {
            if (videoInfo.container && videoInfo.container.parentNode) {
                videoInfo.container.parentNode.removeChild(videoInfo.container);
            }
        });
        remoteVideos.clear();
        remoteUserInfo.clear();

        // mediasoup 소켓 정리
        if (mediasoupSocket) {
            mediasoupSocket.disconnect();
            mediasoupSocket = null;
        }

        // 채팅에 나가기 알림
        if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            const leaveRoomMessage = {
                type: 'leave-room',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                userName: currentUser.userName,
                timestamp: Date.now()
            };
            chatSocket.send(JSON.stringify(leaveRoomMessage));
        }

        isJoined = false;
        dma_videoChat.set("isJoined", "false");

        scwin.updateControlButtons();
        //scwin.addChatMessage("시스템", "화상통화를 나갔습니다.", false);
        console.log("✅ 화상통화 나가기 완료");

        console.log("나가기 함수 실행 중 - 모달 닫기 시작");

        // 프로젝트 설정과 동일한 방식으로 모달 닫기 (projectSettingSideMenu.xml의 btn_back_onclick 로직)
        try {
            console.log("화상통화 모달 닫기 시작 - 프로젝트 설정 방식 적용");

            // 방법 1: 부모의 closeVideoChatModal 함수 직접 호출
            if (window.parent && window.parent.scwin && window.parent.scwin.closeVideoChatModal) {
                console.log("부모의 closeVideoChatModal 함수 호출");
                window.parent.scwin.closeVideoChatModal();
                return; // 성공하면 여기서 끝
            }

            // 방법 2: 최상위 부모의 함수 호출  
            if (window.parent && window.parent.parent && window.parent.parent.scwin && window.parent.parent.scwin.closeVideoChatModal) {
                console.log("최상위 부모의 closeVideoChatModal 함수 호출");
                window.parent.parent.scwin.closeVideoChatModal();
                return; // 성공하면 여기서 끝
            }

            // 방법 3: 직접 부모에게 메시지 전송
            if (window.parent) {
                console.log("부모창에 메시지 전송");
                window.parent.postMessage({action: 'closeVideoChatPopup'}, '*');
            }

            // 방법 4: 최상위 부모에게 메시지 전송
            if (window.parent && window.parent.parent) {
                console.log("최상위 부모창에 메시지 전송");
                window.parent.parent.postMessage({action: 'closeVideoChatPopup'}, '*');
            }

            // 방법 5: 강제 닫기 시도
            console.log("강제 닫기 시도");
            setTimeout(function() {
                if (window.close) {
                    window.close();
                } else if (window.parent && window.parent.close) {
                    window.parent.close();
                } else {
                    window.history.back();
                }
            }, 100);

        } catch(e) {
            console.error("화상통화 모달 닫기 실행 오류:", e);
            // 최후의 수단
            try {
                window.history.back();
            } catch(e2) {
                console.error("history.back도 실패:", e2);
            }
        }


    } catch (error) {
        //console.error("❌ 화상통화 나가기 실패:", error);
    }
};

// 마이크 토글 (mediasoup 방식)
scwin.toggleMute = function() {
    if (!localStream) return;

    const audioTracks = localStream.getAudioTracks();
    if (audioTracks.length > 0) {
        audioTracks[0].enabled = !audioTracks[0].enabled;
        isMuted = !audioTracks[0].enabled;
        dma_videoChat.set("isMuted", isMuted.toString());

        // Audio Producer도 활성화/비활성화
        if (audioProducer) {
            if (isMuted) {
                audioProducer.pause();
                //console.log("������ 오디오 Producer 일시정지");
            } else {
                audioProducer.resume();
                //console.log("������ 오디오 Producer 재시작");
            }
        }

        scwin.updateControlButtons();
        //scwin.addChatMessage("시스템", `${isMuted ? '������ 마이크 음소거' : '������ 마이크 켜짐'}`, false);
    }
};

// 비디오 토글 (mediasoup 방식)
scwin.toggleVideo = function() {
    if (!localStream) return;

    const videoTracks = localStream.getVideoTracks();
    if (videoTracks.length > 0) {
        videoTracks[0].enabled = !videoTracks[0].enabled;
        isVideoOff = !videoTracks[0].enabled;
        dma_videoChat.set("isVideoOff", isVideoOff.toString());

        // Video Producer도 활성화/비활성화
        if (videoProducer) {
            if (isVideoOff) {
                videoProducer.pause();
                //console.log("������ 비디오 Producer 일시정지");
            } else {
                videoProducer.resume();
                //console.log("������ 비디오 Producer 재시작");
            }
        }

        scwin.updateControlButtons();
        //scwin.addChatMessage("시스템", `${isVideoOff ? '������ 비디오 끄기' : '������ 비디오 켜기'}`, false);
    }
};

