// 버튼 상태 업데이트
scwin.updateControlButtons = function() {
    const joinBtn = document.getElementById("joinBtn");
    const leaveBtn = document.getElementById("leaveBtn");
    const muteBtn = document.getElementById("muteBtn");
    const videoBtn = document.getElementById("videoBtn");

    if (isJoined) {
        if (joinBtn) joinBtn.style.display = "none";
        if (leaveBtn) leaveBtn.style.display = "inline-block";
        if (muteBtn) {
            muteBtn.disabled = false;
            muteBtn.textContent = isMuted ? "MUTE" : "MIC";
            muteBtn.className = isMuted ? "control-btn mute-btn muted" : "control-btn mute-btn";
        }
        if (videoBtn) {
            videoBtn.disabled = false;
            videoBtn.textContent = isVideoOff ? "CAM OFF" : "CAM ON";
            videoBtn.className = isVideoOff ? "control-btn video-btn video-off" : "control-btn video-btn";
        }
    } else {
        if (joinBtn) joinBtn.style.display = "inline-block";
        if (leaveBtn) leaveBtn.style.display = "none";
        if (muteBtn) muteBtn.disabled = true;
        if (videoBtn) videoBtn.disabled = true;
    }
};

