// Simple WebRTC 재연결 함수
scwin.forceReconnect = function() {
    if (!isJoined) {
        //console.log("❌ 화상통화에 참가하지 않은 상태");
        //scwin.addChatMessage("시스템", "❌ 먼저 화상통화에 참가해주세요.", false);
        return;
    }

    //console.log("Simple WebRTC 강제 재연결 시작...");
    //scwin.addChatMessage("시스템", "화상통화 연결을 재시작합니다...", false);

    // Simple WebRTC 연결 재시작
    setTimeout(async () => {
        try {
            // 현재 연결 정리
            scwin.leaveCall();

            // 3초 후 재연결
            setTimeout(async () => {
                try {
                    await scwin.joinCall();
                    //scwin.addChatMessage("시스템", "✅ 화상통화 재연결 완료", false);
                } catch (error) {
                    //console.error("❌ 재연결 실패:", error);
                    //scwin.addChatMessage("시스템", "❌ 재연결 실패. 다시 시도해주세요.", false);
                }
            }, 3000);

        } catch (error) {
            //console.error("❌ 연결 정리 실패:", error);
        }
    }, 1000);
};

