// 브라우저 닫기/페이지 나가기 처리 (강화된 버전)
function handlePageExit() {
    try {
        //console.log("������ 페이지 나가기 감지 - 정리 시작");

        if (isJoined) {
            // 즉시 나가기 메시지 전송 (동기 방식)
            if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
                const leaveMessage = {
                    type: 'leave-room',
                    channelName: currentUser.channelName,
                    userId: currentUser.userId,
                    userName: currentUser.userName,
                    timestamp: Date.now()
                };

                // 동기 방식으로 즉시 전송
                chatSocket.send(JSON.stringify(leaveMessage));
                //console.log("✅ 나가기 메시지 즉시 전송");
            }

            // 로컬 스트림 즉시 정지
            if (localStream) {
                localStream.getTracks().forEach(track => track.stop());
                localStream = null;
            }

            // P2P 연결 즉시 종료
            peerConnections.forEach(pc => pc.close());
            peerConnections.clear();

            isJoined = false;
        }

        // WebSocket 연결 종료
        if (chatSocket) {
            chatSocket.close();
        }

        //console.log("✅ 페이지 나가기 정리 완료");

    } catch (error) {
        //console.error("❌ 페이지 나가기 정리 실패:", error);
    }
}

// 1. beforeunload 이벤트 (가장 중요)
window.addEventListener('beforeunload', function(e) {
