    // 브라우저가 확인 대화상자를 표시하지 않도록 함
    // (화상통화 중일 때만 경고 메시지 표시)
    if (isJoined) {
        const message = '화상통화가 진행 중입니다. 정말 나가시겠습니까?';
        e.returnValue = message; // Chrome
        return message; // Firefox
    }
});

