// 미니 PIP 드래그 및 리사이즈 변수들
let isDragging = false;
let isResizing = false;
let dragOffset = { x: 0, y: 0 };
let resizeStart = { x: 0, y: 0, width: 0, height: 0 };

// 미니 PIP 드래그 기능 (강화버전)
scwin.initializePipDrag = function() {
    console.log('������ PIP 드래그 초기화 시작');

    setTimeout(() => {
        const pipContainer = document.querySelector('.mini-pip-container');
        const pipHeader = document.querySelector('.mini-pip-header');

        console.log('������ PIP 요소 찾기:', { 
            container: !!pipContainer, 
            header: !!pipHeader 
        });

        if (!pipContainer || !pipHeader) {
            console.warn('⚠️ PIP 요소를 찾을 수 없음');
            return;
        }

        // 기존 이벤트 리스너 제거
        const clonedHeader = pipHeader.cloneNode(true);
        pipHeader.parentNode.replaceChild(clonedHeader, pipHeader);

        clonedHeader.style.cursor = 'move';
        clonedHeader.addEventListener('mousedown', function(e) {
            console.log('������ 드래그 시작');

            // 닫기 버튼 클릭시 제외
            if (e.target.closest('.mini-pip-close')) {
                console.log('������ 닫기 버튼 클릭 - 드래그 중단');
                return;
            }

            isDragging = true;
            pipContainer.classList.add('dragging');

            const rect = pipContainer.getBoundingClientRect();
            dragOffset.x = e.clientX - rect.left;
            dragOffset.y = e.clientY - rect.top;

            console.log('������ 드래그 오프셋:', dragOffset);

            document.addEventListener('mousemove', handlePipDrag, true);
            document.addEventListener('mouseup', handlePipDragEnd, true);
            e.preventDefault();
            e.stopPropagation();
        }, true);

        console.log('✅ 드래그 이벤트 리스너 등록 완료');
    }, 500);
};

// 미니 PIP 리사이즈 기능
scwin.initializePipResize = function() {
    const pipContainer = document.querySelector('.mini-pip-container');

    if (!pipContainer) return;

    // 기존 리사이즈 핸들 제거
    const existingHandles = pipContainer.querySelectorAll('.resize-handle');
    existingHandles.forEach(handle => handle.remove());

    // 8방향 리사이즈 핸들 생성
    const handles = [
        { class: 'corner nw', cursor: 'nw-resize' },
        { class: 'corner ne', cursor: 'ne-resize' },
        { class: 'corner sw', cursor: 'sw-resize' },
        { class: 'corner se', cursor: 'se-resize' },
        { class: 'edge top', cursor: 'n-resize' },
        { class: 'edge bottom', cursor: 's-resize' },
        { class: 'edge left', cursor: 'w-resize' },
        { class: 'edge right', cursor: 'e-resize' }
    ];

    handles.forEach(handleInfo => {
        const handle = document.createElement('div');
        handle.className = `resize-handle ${handleInfo.class}`;
        handle.style.cursor = handleInfo.cursor;

        handle.addEventListener('mousedown', function(e) {
            isResizing = true;
            pipContainer.classList.add('resizing');

            const rect = pipContainer.getBoundingClientRect();
            resizeStart.x = e.clientX;
            resizeStart.y = e.clientY;
            resizeStart.width = rect.width;
            resizeStart.height = rect.height;
            resizeStart.left = rect.left;
            resizeStart.top = rect.top;
            resizeStart.direction = handleInfo.class;

            document.addEventListener('mousemove', handlePipResize);
            document.addEventListener('mouseup', handlePipResizeEnd);
            e.preventDefault();
            e.stopPropagation();
        });

        pipContainer.appendChild(handle);
    });
};

// 드래그 처리 (강화버전)
function handlePipDrag(e) {
    if (!isDragging) return;

    const pipContainer = document.querySelector('.mini-pip-container');
    if (!pipContainer) return;

    const newX = e.clientX - dragOffset.x;
    const newY = e.clientY - dragOffset.y;

    // 화면 경계 체크
    const maxX = window.innerWidth - pipContainer.offsetWidth;
    const maxY = window.innerHeight - pipContainer.offsetHeight;

    const constrainedX = Math.max(0, Math.min(newX, maxX));
    const constrainedY = Math.max(0, Math.min(newY, maxY));

    // 중요: !important로 스타일 강제 적용
    pipContainer.style.setProperty('left', constrainedX + 'px', 'important');
    pipContainer.style.setProperty('top', constrainedY + 'px', 'important');
    pipContainer.style.setProperty('right', 'auto', 'important');
    pipContainer.style.setProperty('bottom', 'auto', 'important');

    console.log('������ 드래그 위치 업데이트:', { x: constrainedX, y: constrainedY });
}

// 드래그 종료
function handlePipDragEnd() {
    console.log('������ 드래그 종료');
    isDragging = false;
    const pipContainer = document.querySelector('.mini-pip-container');
    if (pipContainer) {
        pipContainer.classList.remove('dragging');
    }
    document.removeEventListener('mousemove', handlePipDrag, true);
    document.removeEventListener('mouseup', handlePipDragEnd, true);
}

// 리사이즈 처리
function handlePipResize(e) {
    if (!isResizing) return;

    const pipContainer = document.querySelector('.mini-pip-container');
    if (!pipContainer) return;

    const deltaX = e.clientX - resizeStart.x;
    const deltaY = e.clientY - resizeStart.y;
    const direction = resizeStart.direction;

    let newWidth = resizeStart.width;
    let newHeight = resizeStart.height;
    let newLeft = resizeStart.left;
    let newTop = resizeStart.top;

    // 방향에 따른 리사이즈 처리
    if (direction.includes('right') || direction.includes('se') || direction.includes('ne')) {
        newWidth = resizeStart.width + deltaX;
    }
    if (direction.includes('left') || direction.includes('sw') || direction.includes('nw')) {
        newWidth = resizeStart.width - deltaX;
        newLeft = resizeStart.left + deltaX;
    }
    if (direction.includes('bottom') || direction.includes('se') || direction.includes('sw')) {
        newHeight = resizeStart.height + deltaY;
    }
    if (direction.includes('top') || direction.includes('ne') || direction.includes('nw')) {
        newHeight = resizeStart.height - deltaY;
        newTop = resizeStart.top + deltaY;
    }

    // 최소/최대 크기 제한
    const minWidth = 250;
    const maxWidth = Math.min(600, window.innerWidth * 0.8);
    const minHeight = 200;
    const maxHeight = window.innerHeight * 0.8;

    if (newWidth < minWidth) {
        if (direction.includes('left')) {
            newLeft = resizeStart.left + (resizeStart.width - minWidth);
        }
        newWidth = minWidth;
    }
    if (newWidth > maxWidth) {
        if (direction.includes('left')) {
            newLeft = resizeStart.left + (resizeStart.width - maxWidth);
        }
        newWidth = maxWidth;
    }

    if (newHeight < minHeight) {
        if (direction.includes('top')) {
            newTop = resizeStart.top + (resizeStart.height - minHeight);
        }
        newHeight = minHeight;
    }
    if (newHeight > maxHeight) {
        if (direction.includes('top')) {
            newTop = resizeStart.top + (resizeStart.height - maxHeight);
        }
        newHeight = maxHeight;
    }

    // 화면 경계 체크
    newLeft = Math.max(0, Math.min(newLeft, window.innerWidth - newWidth));
    newTop = Math.max(0, Math.min(newTop, window.innerHeight - newHeight));

    // 스타일 적용
    pipContainer.style.width = newWidth + 'px';
    pipContainer.style.height = newHeight + 'px';
    pipContainer.style.left = newLeft + 'px';
    pipContainer.style.top = newTop + 'px';
    pipContainer.style.right = 'auto';
    pipContainer.style.bottom = 'auto';
}

// 리사이즈 종료
function handlePipResizeEnd() {
    isResizing = false;
    const pipContainer = document.querySelector('.mini-pip-container');
    if (pipContainer) {
        pipContainer.classList.remove('resizing');
    }
    document.removeEventListener('mousemove', handlePipResize);
    document.removeEventListener('mouseup', handlePipResizeEnd);
}

