// Producer 생성 함수
async function createProducer() {
    try {
        //console.log('�� Producer 생성 시작');

        if (!sendTransport) {
            //console.error('❌ Send Transport가 없습니다');
            return;
        }

        // Transport 연결 상태 확인 (PeerConnection 접근 방법 개선)
        let sendPeerConnection = sendTransport._pc || 
                                sendTransport._handler?.pc || 
                                sendTransport.handler?.pc;

        //console.log('������ Send Transport 상태 확인:', {
            hasPeerConnection: !!sendPeerConnection,
            connectionState: sendPeerConnection?.connectionState,
            iceConnectionState: sendPeerConnection?.iceConnectionState,
            signalingState: sendPeerConnection?.signalingState,
            transportClosed: sendTransport.closed,
            transportConnectionState: sendTransport.connectionState
        });

        // Transport가 연결될 때까지 대기
        if (sendPeerConnection && sendPeerConnection.connectionState !== 'connected') {
            //console.log('⏳ Send Transport 연결 대기 중... 현재 상태:', sendPeerConnection.connectionState);
            await waitForTransportConnection(sendTransport);
        } else if (!sendPeerConnection) {
            //console.log('⚠️ PeerConnection을 찾을 수 없음. Transport 강제 연결 시도');
            // PeerConnection이 없어도 계속 진행 (Transport 이벤트로 연결될 수 있음)
        }

        const stream = await navigator.mediaDevices.getUserMedia({ 
            video: true, 
            audio: true 
        });

        localVideo.srcObject = stream;

        // 비디오 track으로 Producer 생성
        const videoTrack = stream.getVideoTracks()[0];
        const audioTrack = stream.getAudioTracks()[0];

        //console.log('������ Track 정보:', {
            video: {
                id: videoTrack.id,
                kind: videoTrack.kind,
                enabled: videoTrack.enabled,
                readyState: videoTrack.readyState
            },
            audio: {
                id: audioTrack.id,
                kind: audioTrack.kind,
                enabled: audioTrack.enabled,
                readyState: audioTrack.readyState
            }
        });

        // Video Producer 생성
        const videoProducer = await sendTransport.produce({
            track: videoTrack,
            encodings: [{
                maxBitrate: 100000
            }],
            codecOptions: {
                videoGoogleStartBitrate: 1000
            }
        });

        // Audio Producer 생성
        const audioProducer = await sendTransport.produce({
            track: audioTrack
        });

        //console.log('✅ Producer 생성 완료:', {
            video: {
                id: videoProducer.id,
                kind: videoProducer.kind,
                paused: videoProducer.paused,
                closed: videoProducer.closed
            },
            audio: {
                id: audioProducer.id,
                kind: audioProducer.kind,
                paused: audioProducer.paused,
                closed: audioProducer.closed
            }
        });

        // Producer 상태 모니터링
        videoProducer.on('transportclose', () => {
            //console.log('������ Video Producer transport closed');
        });

        videoProducer.on('trackended', () => {
            //console.log('������ Video Producer track ended');
        });

        audioProducer.on('transportclose', () => {
            //console.log('������ Audio Producer transport closed');
        });

        audioProducer.on('trackended', () => {
            //console.log('������ Audio Producer track ended');
        });

        // Producer 생성 후 잠시 대기
        //console.log('⏳ Producer 안정화 대기 중...');
        await new Promise(resolve => setTimeout(resolve, 1000));

        // Transport 상태 재확인
        //console.log('������ Producer 생성 후 Transport 상태:', {
            connectionState: sendTransport._pc?.connectionState,
            iceConnectionState: sendTransport._pc?.iceConnectionState,
            senders: sendTransport._pc?.getSenders()?.length || 0
        });

        // 서버에 Producer 생성 알림
        mediasoupSocket.emit('newProducer', {
            socketId: mediasoupSocket.id,
            userName: currentUser
        });

        //console.log('������ newProducer 이벤트 전송 완료');

    } catch (error) {
        //console.error('❌ Producer 생성 실패:', error);
        alert('카메라/마이크 접근에 실패했습니다: ' + error.message);
    }
}

// Transport 연결 대기 함수
async function waitForTransportConnection(transport) {
    return new Promise((resolve, reject) => {
        let attemptCount = 0;
        const maxAttempts = 60; // 30초 대기 (500ms * 60)

        const checkConnection = () => {
            attemptCount++;

            // PeerConnection 찾기 (여러 방법 시도)
            const pc = transport._pc || 
                      transport._handler?.pc || 
                      transport.handler?.pc;

            if (pc && pc.connectionState === 'connected') {
                //console.log('✅ Transport 연결 완료');
                resolve();
            } else if (pc && pc.connectionState === 'failed') {
                //console.error('❌ Transport 연결 실패');
                reject(new Error('Transport connection failed'));
            } else if (attemptCount >= maxAttempts) {
                //console.warn('⚠️ Transport 연결 대기 시간 초과. 현재 상태로 진행');
                resolve(); // 시간 초과 시에도 진행
            } else {
                //console.log(`⏳ Transport 연결 상태 (${attemptCount}/${maxAttempts}):`, {
                    hasPeerConnection: !!pc,
                    connectionState: pc?.connectionState,
                    transportConnectionState: transport.connectionState,
                    transportClosed: transport.closed
                });
                setTimeout(checkConnection, 500);
            }
        };
        checkConnection();
    });
}

