// ===== Simple WebRTC 관련 추가 함수들 =====

// 화상통화 나가기
scwin.leaveCall = function() {
    try {
        // 모든 P2P 연결 종료
        peerConnections.forEach((pc, userId) => {
            pc.close();
        });
        peerConnections.clear();

        // 로컬 스트림 정지
        if (localStream) {
            localStream.getTracks().forEach(track => track.stop());
            localStream = null;
        }

        // 비디오 요소 초기화
        const localVideo = document.getElementById("localVideo");
        if (localVideo) {
            localVideo.srcObject = null;
        }

        // 원격 비디오 제거
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (remoteVideosGrid) {
            remoteVideosGrid.innerHTML = '';
        }

        // 나가기 알림
        if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            const leaveMessage = {
                type: 'leave-room',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                userName: currentUser.userName,
                timestamp: Date.now()
            };
            chatSocket.send(JSON.stringify(leaveMessage));
        }

        isJoined = false;
        dma_videoChat.set("isJoined", "false");

        // 내 비디오를 그리드에서 제거
        scwin.removeMyVideoFromGrid();

        scwin.updateControlButtons();
        //scwin.addChatMessage("시스템", "화상통화를 나갔습니다. 카메라와 마이크가 꺼졌습니다.", false);

        //console.log("✅ 화상통화 종료 완료");

        // 프로젝트 설정과 동일한 방식으로 모달 닫기 (projectSettingSideMenu.xml의 btn_back_onclick 방식)
        try {
            console.log("화상통화 모달 닫기 시작 - 프로젝트 설정 방식 적용");

            // 방법 1: 부모의 closeVideoChatModal 함수 직접 호출
            if (window.parent && window.parent.scwin && window.parent.scwin.closeVideoChatModal) {
                console.log("방법 1: 부모의 closeVideoChatModal 함수 호출");
                window.parent.scwin.closeVideoChatModal();
                return; // 성공하면 여기서 끝
            }

            // 방법 2: 최상위 부모의 함수 호출  
            if (window.parent && window.parent.parent && window.parent.parent.scwin && window.parent.parent.scwin.closeVideoChatModal) {
                console.log("방법 2: 최상위 부모의 closeVideoChatModal 함수 호출");
                window.parent.parent.scwin.closeVideoChatModal();
                return; // 성공하면 여기서 끝
            }

            // 방법 3: 직접 부모에게 메시지 전송
            if (window.parent) {
                console.log("방법 3: 부모창에 메시지 전송");
                window.parent.postMessage({action: 'closeVideoChatPopup'}, '*');
            }

            // 방법 4: 최상위 부모에게 메시지 전송
            if (window.parent && window.parent.parent) {
                console.log("방법 4: 최상위 부모창에 메시지 전송");
                window.parent.parent.postMessage({action: 'closeVideoChatPopup'}, '*');
            }

            // 방법 5: 강제 닫기 시도
            console.log("방법 5: 강제 닫기 시도");
            setTimeout(function() {
                if (window.close) {
                    console.log("window.close() 시도");
                    window.close();
                } else if (window.parent && window.parent.close) {
                    console.log("window.parent.close() 시도");
                    window.parent.close();
                } else {
                    console.log("history.back() 시도");
                    window.history.back();
                }
            }, 100);

        } catch(closeError) {
            console.error("화상통화 모달 닫기 실행 오류:", closeError);
            // 최후의 수단
            try {
                console.log("최후 수단: history.back()");
                window.history.back();
            } catch(e2) {
                console.error("history.back도 실패:", e2);
            }
        }

    } catch (error) {
        //console.error("❌ 화상통화 종료 실패:", error);
        // 오류 발생 시 모달 닫기 시도
        try {
            if (window.parent && window.parent.scwin && window.parent.scwin.closeVideoChatModal) {
                window.parent.scwin.closeVideoChatModal();
            } else {
                window.history.back();
            }
        } catch (backError) {
            window.location.href = '/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/ui/mainPage.xml';
        }
    }
};

// 음소거 토글
scwin.toggleMute = function() {
    if (localStream) {
        const audioTrack = localStream.getAudioTracks()[0];
        if (audioTrack) {
            audioTrack.enabled = !audioTrack.enabled;
            const muteBtn = document.getElementById("muteBtn");
            if (muteBtn) {
                muteBtn.textContent = audioTrack.enabled ? "MIC" : "음소거";
                muteBtn.classList.toggle("muted", !audioTrack.enabled);
            }

            // 그리드에 있는 내 비디오의 사용자 이름에 음소거 표시
            const myUserNameInGrid = document.querySelector('[data-username="나"] .remote-user-name');
            if (myUserNameInGrid) {
                if (audioTrack.enabled) {
                    myUserNameInGrid.style.background = '#FFB823';
                    myUserNameInGrid.textContent = `나 (${currentUser.userName})`;
                } else {
                    myUserNameInGrid.style.background = '#dc3545';
                    myUserNameInGrid.textContent = `나 (${currentUser.userName}) - 음소거`;
                }
            }

            //console.log("������ 마이크:", audioTrack.enabled ? "켜짐" : "꺼짐");
            //scwin.addChatMessage("시스템", audioTrack.enabled ? "마이크를 켰습니다." : "마이크를 껐습니다.", false);
        }
    }
};

// 비디오 토글
scwin.toggleVideo = function() {
    if (localStream) {
        const videoTrack = localStream.getVideoTracks()[0];
        if (videoTrack) {
            videoTrack.enabled = !videoTrack.enabled;
            const videoBtn = document.getElementById("videoBtn");
            if (videoBtn) {
                videoBtn.textContent = videoTrack.enabled ? "CAM" : "CAM OFF";
                videoBtn.classList.toggle("off", !videoTrack.enabled);
            }

            // 그리드에 있는 내 비디오에도 반영
            const myVideoContainer = document.querySelector('[data-username="나"] .remote-video-player');
            if (myVideoContainer) {
                const myVideoInGrid = myVideoContainer.querySelector('video');
                if (videoTrack.enabled) {
                    if (myVideoInGrid) myVideoInGrid.style.display = 'block';
                    // 카메라 꺼짐 메시지 제거
                    const offMessage = myVideoContainer.querySelector('.camera-off-message');
                    if (offMessage) offMessage.remove();
                } else {
                    if (myVideoInGrid) myVideoInGrid.style.display = 'none';
                    // 카메라 꺼짐 메시지 표시
                    let offMessage = myVideoContainer.querySelector('.camera-off-message');
                    if (!offMessage) {
                        offMessage = document.createElement('div');
                        offMessage.className = 'camera-off-message';
                        offMessage.style.cssText = `
                            position: absolute;
                            top: 50%;
                            left: 50%;
                            transform: translate(-50%, -50%);
                            color: white;
                            font-size: 18px;
                            font-weight: bold;
                            text-align: center;
                            background: rgba(0,0,0,0.7);
                            padding: 10px;
                            border-radius: 8px;
                        `;
                        offMessage.textContent = '카메라 꺼짐';
                        myVideoContainer.appendChild(offMessage);
                    }
                }
            }

            //console.log("������ 카메라:", videoTrack.enabled ? "켜짐" : "꺼짐");
            //scwin.addChatMessage("시스템", videoTrack.enabled ? "카메라를 켰습니다." : "카메라를 껐습니다.", false);
        }
    }
};

// 미니 PIP 모드 상태
let isMiniPipActive = false;

// PIP 상태 저장을 위한 전역 변수
let pipVideoState = null;

// 현재 화상통화 상태를 저장하는 함수
scwin.saveVideoStateToParent = function() {
    console.log("화상통화 상태 저장 시작");

    try {
        // 비디오 엘리먼트들 수집
        const localVideo = document.getElementById('localVideo');
        const remoteVideos = document.querySelectorAll('#remoteVideosGrid video');

        // 상태 정보 저장
        pipVideoState = {
            projectId: projectId,
            channelName: currentUser.channelName,
            userId: currentUser.userId,
            userName: currentUser.userName,
            isJoined: !!localVideo || remoteVideos.length > 0,
            localStream: localVideo ? localVideo.srcObject : null,
            remoteStreams: [],
            participants: []
        };

        // 원격 비디오 정보 저장
        remoteVideos.forEach((video, index) => {
            if (video.srcObject) {
                const container = video.closest('.remote-user-video');
                const nameElement = container ? container.querySelector('.remote-user-name') : null;
                pipVideoState.remoteStreams.push({
                    stream: video.srcObject,
                    userName: nameElement ? nameElement.textContent : `참가자 ${index + 1}`
                });
            }
        });

        // WebRTC 연결 상태 저장
        pipVideoState.webrtcState = {
            mediasoupSocket: mediasoupSocket,
            sendTransport: sendTransport,
            recvTransport: recvTransport,
            device: device,
            videoProducer: videoProducer,
            audioProducer: audioProducer,
            consumers: consumers
        };

        console.log("화상통화 상태 저장 완료:", pipVideoState);

        // 부모 페이지에 상태 전달
        if (window.parent) {
            window.parent.postMessage({
                action: 'saveVideoChatState',
                state: {
                    projectId: pipVideoState.projectId,
                    channelName: pipVideoState.channelName,
                    userId: pipVideoState.userId,
                    userName: pipVideoState.userName,
                    isJoined: pipVideoState.isJoined,
                    remoteStreamsCount: pipVideoState.remoteStreams.length
                }
            }, '*');
        }

    } catch (error) {
        console.error("화상통화 상태 저장 실패:", error);
    }
};

// Picture-in-Picture 토글 상태 변수
let isPipMode = false;

// Picture-in-Picture 토글 (Method 1 - 별도 컨테이너 사용)
scwin.togglePiP = function() {
    console.log('PIP 버튼 클릭됨 - miniPIP 모드 토글, 현재 상태:', isPipMode);

    // 로컬 비디오와 원격 비디오 확인
    const localVideo = document.getElementById('localVideo');
    const remoteVideos = document.querySelectorAll('#remoteVideosGrid video');

    if (!localVideo && remoteVideos.length === 0) {
        alert('비디오를 찾을 수 없습니다. 먼저 화상통화에 참여해주세요.');
        return;
    }

    try {
        if (!isPipMode) {
            // PIP 모드로 전환
            console.log('일반 모드 → PIP 모드 전환 시작');

            // 1. 부모창에 모달 축소 요청
            if (window.parent && window.parent !== window) {
                try {
                    console.log('������ PostMessage 전송 시작 - resizeModalToPip');
                    console.log('window.parent:', window.parent);
                    console.log('window.parent.location:', window.parent.location.href);

                    window.parent.postMessage({
                        action: 'resizeModalToPip',
                        source: 'videoChatPage',
                        timestamp: Date.now()
                    }, '*');
                    console.log('✅ 부모창에 모달 축소 요청 전송 완료');

                    // 추가 확인을 위한 다중 전송
                    setTimeout(() => {
                        window.parent.postMessage({
                            action: 'resizeModalToPip',
                            source: 'videoChatPage_retry',
                            timestamp: Date.now()
                        }, '*');
                        console.log('������ PostMessage 재시도 전송');
                    }, 100);

                } catch (e) {
                    console.error('모달 축소 요청 실패:', e);
                }
            } else {
                console.warn('⚠️ 부모창을 찾을 수 없습니다 - 대체 방법 시도');

                // 대체 방법 1: window.opener 사용
                if (window.opener && window.opener !== window) {
                    try {
                        console.log('������ 대체 방법: window.opener 사용');
                        window.opener.postMessage({
                            action: 'resizeModalToPip',
                            source: 'videoChatPage_opener',
                            timestamp: Date.now()
                        }, '*');
                        console.log('✅ window.opener로 PostMessage 전송 완료');
                    } catch (openerError) {
                        console.error('window.opener 사용 실패:', openerError);
                    }
                }

                // 대체 방법 2: window.top 사용
                else if (window.top && window.top !== window) {
                    try {
                        console.log('������ 대체 방법: window.top 사용');
                        window.top.postMessage({
                            action: 'resizeModalToPip',
                            source: 'videoChatPage_top',
                            timestamp: Date.now()
                        }, '*');
                        console.log('✅ window.top으로 PostMessage 전송 완료');
                    } catch (topError) {
                        console.error('window.top 사용 실패:', topError);
                    }
                }

                // 대체 방법 3: 직접 DOM 접근 시도 (가장 강력함!)
                setTimeout(() => {
                    try {
                        console.log('������ 대체 방법: 직접 DOM 접근 시도');

                        // 1단계: document에서 모달 찾기
                        let modalElement = document.querySelector('[id*="videoChatPopup"]');

                        // 2단계: parent document에서 찾기
                        if (!modalElement && window.parent && window.parent.document) {
                            try {
                                modalElement = window.parent.document.querySelector('[id*="videoChatPopup"]');
                                console.log('������ parent document에서 모달 발견');
                            } catch (parentDocError) {
                                console.log('parent document 접근 실패:', parentDocError.message);
                            }
                        }

                        // 3단계: top document에서 찾기
                        if (!modalElement && window.top && window.top.document) {
                            try {
                                modalElement = window.top.document.querySelector('[id*="videoChatPopup"]');
                                console.log('������ top document에서 모달 발견');
                            } catch (topDocError) {
                                console.log('top document 접근 실패:', topDocError.message);
                            }
                        }

                        if (modalElement) {
                            console.log('������ 모달 요소 발견:', modalElement.id);

                            // 직접 스타일 수정으로 PIP 모드 적용
                            modalElement.style.setProperty('width', '320px', 'important');
                            modalElement.style.setProperty('height', '240px', 'important');
                            modalElement.style.setProperty('position', 'fixed', 'important');
                            modalElement.style.setProperty('bottom', '20px', 'important');
                            modalElement.style.setProperty('right', '20px', 'important');
                            modalElement.style.setProperty('top', 'auto', 'important');
                            modalElement.style.setProperty('left', 'auto', 'important');
                            modalElement.style.setProperty('z-index', '999999', 'important');

                            console.log('✅ 직접 DOM 조작으로 모달 PIP 적용 완료!');
                        } else {
                            console.log('❌ 모든 document에서 모달 요소를 찾을 수 없음');
                        }
                    } catch (domError) {
                        console.error('직접 DOM 접근 실패:', domError);
                    }
                }, 100);
            }

            // 2. 내부 UI를 PIP 모드로 변경
            scwin.applyPipModeUI();
            isPipMode = true;

            // PIP 버튼 텍스트 변경
            const pipBtn = document.getElementById('pipBtn');
            if (pipBtn) {
                const pipLabel = pipBtn.querySelector('xf\\:label, label');
                if (pipLabel) pipLabel.textContent = '확대';
                pipBtn.classList.add('active');
            }

        } else {
            // 일반 모드로 복원
            console.log('PIP 모드 → 일반 모드 복원 시작');

            // 1. 부모창에 모달 복원 요청
            if (window.parent && window.parent !== window) {
                try {
                    console.log('������ PostMessage 전송 시작 - expandModalFromPip');

                    window.parent.postMessage({
                        action: 'expandModalFromPip',
                        source: 'videoChatPage',
                        timestamp: Date.now()
                    }, '*');
                    console.log('✅ 부모창에 모달 복원 요청 전송 완료');

                } catch (e) {
                    console.error('모달 복원 요청 실패:', e);
                }
            } else {
                console.warn('⚠️ 부모창을 찾을 수 없습니다');
            }

            // 2. 내부 UI를 일반 모드로 복원
            scwin.restoreUIFromPip();
            isPipMode = false;

            // PIP 버튼 텍스트 변경
            const pipBtn = document.getElementById('pipBtn');
            if (pipBtn) {
                const pipLabel = pipBtn.querySelector('xf\\:label, label');
                if (pipLabel) pipLabel.textContent = 'PIP';
                pipBtn.classList.remove('active');
            }
        }

    } catch (error) {
        console.error('PIP 토글 실패:', error);
        alert('PIP 모드 전환에 실패했습니다: ' + error.message);
    }
};

// PIP 모드 UI 적용
scwin.applyPipModeUI = function() {
    console.log('PIP 모드 UI 적용 시작');

    setTimeout(() => {
        const mainContainer = document.querySelector('.video-chat-container');
        const chatSection = document.querySelector('.chat-section');
        const controlPanel = document.querySelector('.control-panel');
        const localVideoContainer = document.querySelector('.local-video-container');

        if (mainContainer) {
            // 메인 컨테이너를 PIP 레이아웃으로 변경
            mainContainer.style.setProperty('flex-direction', 'column', 'important');
            mainContainer.style.setProperty('height', '100%', 'important');
            console.log('✅ 메인 컨테이너 PIP 레이아웃 적용');
        }

        // 채팅 섹션 숨기기
        if (chatSection) {
            chatSection.style.setProperty('display', 'none', 'important');
            console.log('✅ 채팅 섹션 숨김');
        }

        // 컨트롤 패널 PIP용으로 축소
        if (controlPanel) {
            controlPanel.style.setProperty('bottom', '5px', 'important');
            controlPanel.style.setProperty('gap', '5px', 'important');

            // 컨트롤 버튼들 축소
            const controlBtns = controlPanel.querySelectorAll('.control-btn');
            controlBtns.forEach(btn => {
                btn.style.setProperty('width', '30px', 'important');
                btn.style.setProperty('height', '30px', 'important');
                btn.style.setProperty('font-size', '10px', 'important');
            });
            console.log('✅ 컨트롤 패널 PIP 크기로 축소');
        }

        // 로컬 비디오를 더 작게 조정
        if (localVideoContainer) {
            localVideoContainer.style.setProperty('width', '80px', 'important');
            localVideoContainer.style.setProperty('height', '60px', 'important');
            localVideoContainer.style.setProperty('top', '5px', 'important');
            localVideoContainer.style.setProperty('right', '5px', 'important');
            console.log('✅ 로컬 비디오 PIP 크기로 축소');
        }

        // 원격 비디오 그리드 조정
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (remoteVideosGrid) {
            remoteVideosGrid.style.setProperty('padding', '5px', 'important');
            remoteVideosGrid.style.setProperty('grid-gap', '3px', 'important');
            remoteVideosGrid.style.setProperty('grid-template-columns', '1fr', 'important');
            console.log('✅ 원격 비디오 그리드 PIP 레이아웃 적용');
        }

    }, 100);
};

// PIP에서 복원 메시지 처리
window.addEventListener('message', function(event) {
    if (event.data && event.data.action === 'restoreFromPip') {
        console.log('PIP에서 복원 요청 받음');
        scwin.restoreUIFromPip();
        isPipMode = false;

        // PIP 버튼 텍스트 변경
        const pipBtn = document.getElementById('pipBtn');
        if (pipBtn) {
            const pipLabel = pipBtn.querySelector('xf\\:label, label');
            if (pipLabel) pipLabel.textContent = 'PIP';
            pipBtn.classList.remove('active');
        }
    }
});

// PIP에서 UI 복원
scwin.restoreUIFromPip = function() {
    console.log('UI를 PIP에서 일반 모드로 복원 시작');

    try {
        const mainContainer = document.querySelector('.video-chat-container');
        const chatSection = document.querySelector('.chat-section');
        const controlPanel = document.querySelector('.control-panel');
        const localVideoContainer = document.querySelector('.local-video-container');

        // 메인 컨테이너 복원
        if (mainContainer) {
            mainContainer.style.removeProperty('flex-direction');
            mainContainer.style.removeProperty('height');
            console.log('✅ 메인 컨테이너 복원');
        }

        // 채팅 섹션 복원
        if (chatSection) {
            chatSection.style.removeProperty('display');
            console.log('✅ 채팅 섹션 복원');
        }

        // 컨트롤 패널 복원
        if (controlPanel) {
            controlPanel.style.removeProperty('bottom');
            controlPanel.style.removeProperty('gap');

            // 컨트롤 버튼들 복원
            const controlBtns = controlPanel.querySelectorAll('.control-btn');
            controlBtns.forEach(btn => {
                btn.style.removeProperty('width');
                btn.style.removeProperty('height');
                btn.style.removeProperty('font-size');
            });
            console.log('✅ 컨트롤 패널 복원');
        }

        // 로컬 비디오 복원
        if (localVideoContainer) {
            localVideoContainer.style.removeProperty('width');
            localVideoContainer.style.removeProperty('height');
            localVideoContainer.style.removeProperty('top');
            localVideoContainer.style.removeProperty('right');
            console.log('✅ 로컬 비디오 복원');
        }

        // 원격 비디오 그리드 복원
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (remoteVideosGrid) {
            remoteVideosGrid.style.removeProperty('padding');
            remoteVideosGrid.style.removeProperty('grid-gap');
            remoteVideosGrid.style.removeProperty('grid-template-columns');
            console.log('✅ 원격 비디오 그리드 복원');
        }

        console.log('✅ UI 복원 완료');

    } catch (error) {
        console.error('UI 복원 실패:', error);
    }
};

// 비디오 상태를 부모 페이지에 저장하는 함수
scwin.saveVideoStateToParent = function() {
    try {
        console.log('비디오 상태를 부모 페이지에 저장 시작');

        // 현재 비디오 상태 수집
        const videoState = {
            localStream: localStream,
            peerConnections: peerConnections,
            currentUser: currentUser,
            isJoined: isJoined,
            isMuted: isMuted,
            isVideoOff: isVideoOff,
            remoteStreams: remoteStreams,
            remoteUserInfo: remoteUserInfo,
            chatSocket: chatSocket
        };

        // 부모 페이지에 비디오 상태 저장
        if (window.parent && window.parent.scwin) {
            window.parent.scwin.videoConnectionState = videoState;
            console.log('✅ 부모 페이지에 비디오 상태 저장 완료');
        }

        // 로컬 스토리지에도 임시 저장 (백업용)
        try {
            const simpleState = {
                userId: currentUser.userId,
                userName: currentUser.userName,
                channelName: currentUser.channelName,
                isJoined: isJoined,
                isMuted: isMuted,
                isVideoOff: isVideoOff,
                participantCount: peerConnections.size
            };
            localStorage.setItem('tempVideoChatState', JSON.stringify(simpleState));
        } catch (e) {
            console.warn('로컬 스토리지 저장 실패:', e);
        }

    } catch (error) {
        console.error('비디오 상태 저장 실패:', error);
    }
};

// PIP 새창 열기
scwin.openPipWindow = function() {
    console.log('PIP 새창 생성 시작');

    // 새창 옵션 설정 (작고 오른쪽 하단에 위치)
    const screenWidth = window.screen.availWidth;
    const screenHeight = window.screen.availHeight;
    const pipWidth = 400;
    const pipHeight = 300;
    const pipLeft = screenWidth - pipWidth - 20; // 오른쪽에서 20px 떨어짐
    const pipTop = screenHeight - pipHeight - 60; // 아래에서 60px 떨어짐 (작업표시줄 고려)

    const windowFeatures = [
        `width=${pipWidth}`,
        `height=${pipHeight}`,
        `left=${pipLeft}`,
        `top=${pipTop}`,
        'resizable=yes',
        'scrollbars=yes',
        'toolbar=no',
        'menubar=no',
        'location=no',
        'directories=no',
        'status=no'
    ].join(',');

    // 현재 화상통화 페이지 URL 가져오기
    const currentUrl = window.location.href;

    // PIP 모드 파라미터 추가
    const pipUrl = currentUrl + (currentUrl.includes('?') ? '&' : '?') + 'pipMode=true';

    console.log('PIP 새창 URL:', pipUrl);
    console.log('새창 옵션:', windowFeatures);

    // 새창 열기
    const pipWindow = window.open(pipUrl, 'pipVideoChat', windowFeatures);

    if (!pipWindow) {
        throw new Error('팝업이 차단되었습니다. 브라우저 팝업 차단을 해제해주세요.');
    }

    // 새창 포커스
    pipWindow.focus();

    console.log('PIP 새창 생성 완료');
    return pipWindow;
};

// PIP 종료 이벤트 리스너 등록
scwin.setupPipEventListeners = function() {
    // PIP 종료 이벤트 감지
    document.addEventListener('leavepictureinpicture', function(event) {
        console.log('PIP 모드가 종료되었습니다.');
        // 필요시 화상통화 페이지로 돌아가는 로직 추가
    });

    // PIP 시작 이벤트 감지
    document.addEventListener('enterpictureinpicture', function(event) {
        console.log('PIP 모드가 시작되었습니다.');
        // PIP 버튼 상태 업데이트
        const pipBtn = document.getElementById('pipBtn');
        if (pipBtn) {
            pipBtn.classList.add('active');
        }
    });

    console.log('PIP 이벤트 리스너 등록 완료');
};

// 미니 PIP 표시 (원래 방식: 별도 PIP 컨테이너)
scwin.showMiniPIP = function() {
    console.log('showMiniPIP 호출 - 별도 PIP 컨테이너 방식');

    const miniPipContainer = document.getElementById('miniPipContainer');
    const mainContainer = document.querySelector('.video-chat-container');

    if (!miniPipContainer || !mainContainer) {
        console.error('필요한 요소를 찾을 수 없음');
        return;
    }

    // 1. 메인 화상통화 영역 숨기기
    mainContainer.style.display = 'none';
    console.log('메인 컨테이너 숨김');

    // 2. 미니 PIP 컨테이너 표시 (강제로 보이게 설정)
    miniPipContainer.style.setProperty('display', 'block', 'important');
    miniPipContainer.style.setProperty('visibility', 'visible', 'important');
    miniPipContainer.style.setProperty('opacity', '1', 'important');

    // 3. 위치 강제 설정
    miniPipContainer.style.setProperty('position', 'fixed', 'important');
    miniPipContainer.style.setProperty('bottom', '20px', 'important');
    miniPipContainer.style.setProperty('right', '20px', 'important');
    miniPipContainer.style.setProperty('z-index', '9999', 'important');

    // 4. PIP 크기에 맞춰 비디오 그리드 레이아웃 적용
    scwin.updateVideoGridLayout(miniPipContainer);

    console.log('미니 PIP 컨테이너 상태 확인:', {
        display: miniPipContainer.style.display,
        visibility: miniPipContainer.style.visibility,
        opacity: miniPipContainer.style.opacity,
        position: miniPipContainer.style.position,
        bottom: miniPipContainer.style.bottom,
        right: miniPipContainer.style.right,
        zIndex: miniPipContainer.style.zIndex,
        offsetWidth: miniPipContainer.offsetWidth,
        offsetHeight: miniPipContainer.offsetHeight,
        getBoundingClientRect: miniPipContainer.getBoundingClientRect()
    });

    // 5. 비디오들을 미니 PIP에 복사
    scwin.updateMiniPIP();

    // 6. PIP 상태 설정
    isMiniPipActive = true;
    scwin.updatePiPButton(true);

    console.log('미니 PIP 표시 완료');
};

