    if (localVideo) {
        localVideo.style.removeProperty('width');
        localVideo.style.removeProperty('height');
        localVideo.style.removeProperty('object-fit');
        localVideo.style.removeProperty('border-radius');
    }

    if (localContainer) {
        localContainer.style.removeProperty('width');
        localContainer.style.removeProperty('height');
        localContainer.style.removeProperty('margin');
    }

    // 원격 비디오들 복원
    const remoteVideosGrid = document.getElementById('remoteVideosGrid');
    if (remoteVideosGrid) {
        remoteVideosGrid.style.removeProperty('height');
        remoteVideosGrid.style.removeProperty('grid-template-columns');
        remoteVideosGrid.style.removeProperty('grid-gap');
        remoteVideosGrid.style.removeProperty('padding');
    }

    const remoteVideos = document.querySelectorAll('.remote-video');
    remoteVideos.forEach(function(video) {
        video.style.removeProperty('width');
        video.style.removeProperty('height');
        video.style.removeProperty('object-fit');
        video.style.removeProperty('border-radius');
    });

    const remoteContainers = document.querySelectorAll('.remote-video-container');
    remoteContainers.forEach(function(container) {
